SELECT 
FROM sys_user
WHERE tenant_id = #{tenantId} AND id = #{id}

SELECT DISTINCT u.id, u.display_name, u.team_id, t.team_name FROM sys_user u INNER JOIN sys_user_role ur ON ur.tenant_id = u.tenant_id AND ur.user_id = u.id INNER JOIN sys_role r ON r.tenant_id = u.tenant_id AND r.id = ur.role_id AND r.status = 'ACTIVE' AND r.role_code IN #{rc} LEFT JOIN sys_team t ON t.tenant_id = u.tenant_id AND t.id = u.team_id WHERE u.tenant_id = #{tenantId} AND u.status = 'ACTIVE' AND u.user_type = 'EMPLOYEE'
AND u.team_id = #{teamIdEq}
AND u.id = #{userIdEq}
ORDER BY u.id ASC

