UPDATE sys_user SET display_name = #{displayName}, team_id = #{teamId},
password_hash = #{passwordHash},
version = version + 1 WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{version}

UPDATE sys_user
SET status = #{status}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{id}
